CREATE OR REPLACE FUNCTION public.folha_auditar() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE r jsonb=to_jsonb(COALESCE(NEW,OLD)); u uuid; BEGIN u=COALESCE(auth.uid(),NULLIF(current_setting('folha.usuario',true),'')::uuid); INSERT INTO public.folha_auditoria(tabela,registro_id,unidade_id,competencia,acao,antes,depois,user_id) VALUES(TG_TABLE_NAME,CASE WHEN TG_TABLE_NAME IN ('folha_config') THEN NULL ELSE NULLIF(r->>'id','')::uuid END,NULLIF(r->>'unidade_id','')::uuid,r->>'competencia',TG_OP,CASE WHEN TG_OP<>'INSERT' THEN to_jsonb(OLD) END,CASE WHEN TG_OP<>'DELETE' THEN to_jsonb(NEW) END,u); RETURN COALESCE(NEW,OLD); END $$;
CREATE OR REPLACE FUNCTION public.folha_validar_ajustes() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE a jsonb; ajustes jsonb; BEGIN IF NOT EXISTS(SELECT 1 FROM public.folha_colaboradores WHERE id=NEW.colaborador_id AND unidade_id=NEW.unidade_id AND tipo<>'SEM_CONTRATO') THEN RAISE EXCEPTION 'Colaborador fora da unidade ou vínculo sem regra'; END IF; ajustes=COALESCE(NEW.dados->'ajustes','[]'::jsonb); IF jsonb_typeof(ajustes)<>'array' OR jsonb_array_length(ajustes)>100 THEN RAISE EXCEPTION 'Ajustes inválidos'; END IF; IF (SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(ajustes) x)<>jsonb_array_length(ajustes) THEN RAISE EXCEPTION 'Ajustes com identidade duplicada'; END IF; FOR a IN SELECT * FROM jsonb_array_elements(ajustes) LOOP IF length(trim(COALESCE(a->>'descricao','')))=0 OR COALESCE(a->>'tipo','') NOT IN ('adicional','desconto') OR length(trim(COALESCE(a->>'id','')))=0 OR jsonb_typeof(a->'valor') IS DISTINCT FROM 'number' OR (a->>'valor')::numeric<0 OR (a->>'valor')::numeric>1000000 THEN RAISE EXCEPTION 'Adicional/desconto exige descrição, tipo e valor válido'; END IF; END LOOP; RETURN NEW; END $$;